import re
from pathlib import Path

V = Path(r"C:\Users\eric_rash\Desktop\SecondBrain\Knowledge\library")
known = set()
for p in V.rglob("*.md"):
    r = p.relative_to(V).with_suffix("").as_posix()
    known |= {p.stem, r, p.parent.name + "/" + p.stem}
bad = []
for p in V.rglob("*.md"):
    for l in re.findall(r"\[\[([^\]|#\n]+)", p.read_text(encoding="utf-8")):
        l = l.strip().removesuffix(".md")
        if l not in known and l.split("/")[-1] not in known:
            bad.append((p.relative_to(V).as_posix(), l))
print("vault-wide unresolved links:", len(bad))
for b in bad[:25]:
    print(b)

