import re
t=open('z2e.md',encoding='utf-8').read()
pages=re.split(r'<!-- page (\d+) -->',t)[1:]
d={int(pages[i]):pages[i+1] for i in range(0,len(pages),2)}
print('pdf pages:',len(d),min(d),max(d))
# chapter openings
for n,txt in sorted(d.items()):
    m=re.search(r'^\s*CHAPTER\s*(\d+)\s*$|^\s*Chapter\s*(\d+)\s*$',txt,re.M)
    if m and n>12: print('chapter',m.group(1) or m.group(2),'at pdf',n)
# printed page numbers: standalone numbers on first/last 3 lines
prev=None;jumps=[]
seq=[]
for n,txt in sorted(d.items()):
    lines=[l.strip() for l in txt.strip().splitlines() if l.strip()]
    cand=[int(x) for l in lines[:3]+lines[-4:] for x in re.findall(r'^(\d{1,3})\b|\b(\d{1,3})$',l) for x in x if x]
    cand=[c for c in cand if 1<=c<=300]
    seq.append((n,cand[:3]))
for n,c in seq[::10]: print(n,c)
print('last pages:'); 
for n in range(240,248): print(n,(d.get(n,'')[:120]).replace(chr(10),' | '))
"

